"""
This file computes the number of IDs for the model

--experiments: JSON file listing the model needed, number of ED, and embeddings, can use configs/experiments.json (REQUIRED)

--samples: JSON file generated by make_samples.py (REQUIRED)

--out_dir: directory for output (defaults to runs/)

--k: number of nearest neighbors for kNN

--repeats: number of repetitions

--seed_base: seed for random number generation, defualts to 2025
"""

import os
import sys
sys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import argparse
import json
from pathlib import Path
import numpy as np
import pandas as pd

from utils.lid_utils import (
    load_glove_txt,
    build_unique_token_matrix,
    build_abstract_matrix,
    faiss_knn_radii,
    lid_mle_safe,
    global_id,
)


def load_abstracts(path):
    with path.open("r", encoding="utf-8") as f:
        return [ln.strip() for ln in f if ln.strip()]


def run_one_condition(sample_path, emb_path, ED, k_list, seed):
    rng = np.random.default_rng(seed)

    abstracts = load_abstracts(sample_path)
    emb = load_glove_txt(str(emb_path), ED)

    X_tok, _ = build_unique_token_matrix(abstracts, emb, max_unique=50_000)
    X_abs = build_abstract_matrix(abstracts, emb)

    result = {
        "dataset": "arxiv_cs",
        "sample_file": sample_path.name,
        "model_file": emb_path.name,
        "ED": ED,
        "seed": seed,
        "num_unique_tokens": 0 if X_tok is None else int(len(X_tok)),
        "k_results": {},
    }

    if X_tok is not None and len(X_tok) > max(k_list) + 5:
        Xt = X_tok
        for k in k_list:
            R = faiss_knn_radii(Xt, k)
            lids = lid_mle_safe(R)
            if len(lids) == 0:
                continue
            gid = global_id(lids)
            result["k_results"][f"token_k={k}"] = {
                "global_id": float(gid),
                "ratio": float(gid / ED),
                "lid_mean": float(np.mean(lids)),
                "lid_std": float(np.std(lids)),
                "n_points": int(len(Xt)),
            }

    if X_abs is not None and len(X_abs) > max(k_list) + 5:
        n = len(X_abs)
        take = min(n, 20_000)
        idx = rng.choice(n, take, replace=False)
        Xa = X_abs[idx]
        for k in k_list:
            R = faiss_knn_radii(Xa, k)
            lids = lid_mle_safe(R)
            if len(lids) == 0:
                continue
            gid = global_id(lids)
            result["k_results"][f"abs_k={k}"] = {
                "global_id": float(gid),
                "ratio": float(gid / ED),
                "lid_mean": float(np.mean(lids)),
                "lid_std": float(np.std(lids)),
                "n_points": int(len(Xa)),
            }

    return result


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--experiments", type=str, required=True)
    ap.add_argument("--samples", type=str, nargs="+", required=True)
    ap.add_argument("--out_dir", type=str, default="runs")
    ap.add_argument("--k", type=int, nargs="+", default=[10, 20, 50, 100])
    ap.add_argument("--repeats", type=int, default=3)
    ap.add_argument("--seed_base", type=int, default=2025)
    args = ap.parse_args()

    exps = json.loads(Path(args.experiments).read_text(encoding="utf-8"))
    out_dir = Path(args.out_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    rows = []

    for exp in exps:
        emb_path = Path(exp["path"])
        ED = int(exp["ED"])
        model = exp.get("model", emb_path.stem)

        for sample in args.samples:
            sample_path = Path(sample)
            for r in range(args.repeats):
                seed = args.seed_base + r
                res = run_one_condition(sample_path, emb_path, ED, args.k, seed)

                tag = f"{sample_path.stem}_{model}_ED{ED}_rep{r}"
                (out_dir / f"{tag}.json").write_text(json.dumps(res, indent=2), encoding="utf-8")

                for kkey, vals in res["k_results"].items():
                    level = "token" if kkey.startswith("token") else "abstract"
                    k = int(kkey.split("=")[1])
                    rows.append({
                        "dataset": res["dataset"],
                        "sample_file": res["sample_file"],
                        "model": model,
                        "ED": ED,
                        "rep": r,
                        "level": level,
                        "k": k,
                        "global_id": vals["global_id"],
                        "ratio": vals["ratio"],
                        "lid_mean": vals["lid_mean"],
                        "lid_std": vals["lid_std"],
                        "n_points": vals["n_points"],
                        "num_unique_tokens": res.get("num_unique_tokens", None),
                    })

    df = pd.DataFrame(rows)
    csv_path = out_dir / "id_results.csv"
    df.to_csv(csv_path, index=False)
    print("Wrote:", csv_path)
    print(df.head())


if __name__ == "__main__":
    main()
